const float PI = 3.14159265;

float angular_difference(float a, float b) {
    float diff = a - b;
    return mod(diff + PI, 2.0 * PI) - PI;
}

float rand(vec2 co){
    return fract(sin(dot(co, vec2(12.9898, 78.233))) * 43758.5453);
}

vec2 rand2(vec2 co) {
    return vec2(rand(co), rand(co + 1.0));
}

float beam(vec2 uv, vec2 pos, float angle, float len) {
    // Calculate moving point c2 and its negative c1
    vec2 c2 = vec2(cos(angle), sin(angle)) * len;
    vec2 c1 = -c2;

    c2 -= pos;
    c1 -= pos;

    // Compute vectors from UV to c1 and c2
    vec2 v1 = c1 - uv;
    vec2 v2 = c2 - uv;

    // Calculate angle between v1 and v2 using atan2 of cross and dot products
    float a1 = atan(v1.y, v1.x);
    float a2 = atan(v2.y, v2.x);
    float angle_diff = angular_difference(a1, a2);

    // Compute luminance
    float lum = angle_diff / PI;

    return clamp(lum * abs(lum), 0.0, 1.0);
    //return lum * lum; // For a double-sided light
}

vec3 aces_approx(vec3 v)
{
    v *= 0.6f;
    float a = 2.51f;
    float b = 0.03f;
    float c = 2.43f;
    float d = 0.59f;
    float e = 0.14f;
    return clamp((v*(a*v+b))/(v*(c*v+d)+e), 0.0f, 1.0f);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize and center UV coordinates
    vec2 uv = (fragCoord.xy / iResolution.xy - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);

    float acc = beam(uv, vec2(0, 0.0), iTime, 0.3);

    // Output to screen with proper alpha channel
    fragColor = vec4(pow(aces_approx(vec3(acc) * vec3(1, 0.75, 0.5)), vec3(1.0 / 2.2)), 1.0);
}
